task automatic process_sim_bit_compare_mismatch;
   input reg [8*68:1] chain_name;
   input reg [8*68:1] chain_name_org;
   input reg [8*90:1] cell_name;
   input reg sim_value;
   input reg exp_value;
   input integer cell_index;
   begin
        $write($realtime, "ns: Mismatch at chain %s cell %d name %s, Simulated %b, Expected %b\n",chain_name,cell_index,cell_name,sim_value,exp_value);
        if (_write_DIAG_file == 1) begin
          if (_DIAG_file_header == 0) begin
            if ((_start_pat > -1) && (_end_pat > -1)) begin
              $sformat(_tmp_filename, "msrv_soc_uncorewrapper_stuck_parallel.v_%0d_%0d.fail",
                       _start_pat, _end_pat);
            end
            else if (_start_pat > -1) begin
              $sformat(_tmp_filename, "msrv_soc_uncorewrapper_stuck_parallel.v_%0d.fail",
                       _start_pat);
            end
            else if (_end_pat > -1) begin
              $sformat(_tmp_filename, "msrv_soc_uncorewrapper_stuck_parallel.v__%0d.fail",
                       _end_pat);
            end
            else begin
              $sformat(_tmp_filename, "msrv_soc_uncorewrapper_stuck_parallel.v.fail");
            end
            if(_change_out_path) begin 
              $sformat(_tmp_filename, "%0s/%0s", _new_out_path, _tmp_filename);
            end
            _diag_file = $fopen(_tmp_filename);
            if (_diag_file == 0) begin
              $display("ERROR: Couldn't open .fail file %0s, simulation aborted\n", _tmp_filename);
              ->before_finish;
              #0;
              $finish;
            end
            if(_change_out_path) begin 
              $fwrite(_diag_file, "// This File is simulation generated (%0s/msrv_soc_uncorewrapper_stuck_parallel.v)\n", _new_out_path);
            end
            else begin
              $fwrite(_diag_file, "// This File is simulation generated (msrv_soc_uncorewrapper_stuck_parallel.v)\n");
            end
            $fwrite(_diag_file, "//format pattern\n");
            $fwrite(_diag_file, "//failure_buffer_limit_reached none\n");
            $fwrite(_diag_file, "//data_reference cell\n");
            $fwrite(_diag_file, "//pattern_id      chain/PO_name   cell_number   expected_value   simulated_value\n\n");
            _DIAG_file_header = 1;
          end
          if ((_chain_test_)&&(_diag_chain_header!=1)) begin
            $fwrite(_diag_file, "chain_test\n");
            _diag_chain_header = 1;
          end
          if ((_chain_test_!=1)&&(_diag_scan_header!=1)) begin
            $fwrite(_diag_file, "scan_test\n");
            _diag_scan_header = 1;
          end
          $fwrite(_diag_file, "%d  %s %d ", _pattern_count, chain_name_org, cell_index );
          if ((_pattern_count == _last_fail_pattern) && (_pattern_count == 0)) begin 
              _fail_pattern_cnt = 1; 
          end
          if (_pattern_count > _last_fail_pattern) begin 
             _fail_pattern_cnt = _fail_pattern_cnt + 1;
             _last_fail_pattern = _pattern_count;
          end

          case ( exp_value )
            1'b1: begin
                    $fwrite(_diag_file, " H"); 
                  end
            1'b0: begin
                    $fwrite(_diag_file, " L"); 
                  end
            1'bZ: begin
                    $fwrite(_diag_file, " Z"); 
                  end
          endcase
          case ( sim_value )
            1'b1: begin
                    $fwrite(_diag_file, " H  // %s\n", cell_name);
                  end
            1'b0: begin
                    $fwrite(_diag_file, " L  // %s\n", cell_name);
                  end
            1'bZ: begin
                    $fwrite(_diag_file, " Z  // %s\n", cell_name);
                  end
            1'bX: begin
                    $fwrite(_diag_file, " X  // %s\n", cell_name);
                  end
          endcase
        end
        if (_write_MASK_file == 1) begin
          if (_MASK_file_header == 0) begin
            if ((_start_pat > -1) && (_end_pat > -1)) begin
              $sformat(_tmp_filename, "msrv_soc_uncorewrapper_stuck_parallel.v_%0d_%0d.mask",
                       _start_pat, _end_pat);
            end
            else if (_start_pat > -1) begin
              $sformat(_tmp_filename, "msrv_soc_uncorewrapper_stuck_parallel.v_%0d.mask",
                       _start_pat);
            end
            else if (_end_pat > -1) begin
              $sformat(_tmp_filename, "msrv_soc_uncorewrapper_stuck_parallel.v__%0d.mask",
                       _end_pat);
            end
            else begin
              $sformat(_tmp_filename, "msrv_soc_uncorewrapper_stuck_parallel.v.mask");
            end
            if(_change_out_path) begin 
              $sformat(_tmp_filename, "%0s/%0s", _new_out_path, _tmp_filename);
            end
            _mask_file = $fopen(_tmp_filename);
            if (_mask_file == 0) begin
              $display("ERROR: Couldn't open .mask file %0s, simulation aborted\n", _tmp_filename);
              ->before_finish;
              #0;
              $finish;
            end
            $fwrite(_mask_file, "%s\n%s\n", "type mask", "");
            _MASK_file_header = 1;
          end
          if (_chain_test_ == 0) begin
            $fwrite(_mask_file, "%d %s %d\n",
             _pattern_count,chain_name_org,_report_bit_cnt);
          end
          if (_chain_test_ == 1) begin
            $fwrite(_mask_file, "// %d %s %d\n",
             _pattern_count,chain_name,_report_bit_cnt);
          end
        end
   end
endtask


